  const other = evaluate({ policies: [allow({ Action: 's3:PutObject' })] }, get('arn:aws:s3:::b/k'));
  assert.equal(other.reason, 'implicit-deny');
  assert.equal(other.trace[0]!.why, 'action did not match');
});

